Method.Implementation:
$$$TRACE("Inside  Method OnGetConnections")
Do ##super(.pArray,pItem)
set numIn = 10
For j=0:1:numIn-1{
If pItem.GetModifiedSetting("TpdsMedicareExtractClaimsTargetConfigName",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue_"-"_j,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
}

For j=0:1:numIn-1{
If pItem.GetModifiedSetting("ShMedicare837TargetConfigName",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue_"-"_j,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
}

	#dim tmpStatus AS %Status=$$$OK

	set tRequest = ##class(Ens.StreamContainer).%New("")	 
	 set tStream = ##class(%Stream.GlobalCharacter).%New("")
	 set respStr = "<AppResponse><ReturnCode>"_retCode_"</ReturnCode><ReturnDesc>"_retDesc_"</ReturnDesc></AppResponse>"	 
	 do tStream.Write(respStr)	 
	 set tRequest.Stream = tStream	 

	 set claimsResponseFileTargetConfigName=##class(Ens.Director).GetItemSettingValue(process1.%ConfigName,"Host","ClaimsResponseFileTargetConfigName",.pstatus)
 	 if ($$$ISOK(pstatus)){
 		$$$TRACE("ClaimsResponseFileTargetConfigName:: " _ claimsResponseFileTargetConfigName) 	
 	 }	 
 	 set reqObj =##class(IHC.ITF.ITFCOMMON.Request.FileIO).%New(tRequest.Stream)
 	 set reqObj.DestinationFileName = scheduleId_".xml"
	 set reqObj.DestinationFilePath = destinationFilePath_"BiztalkScheduler/Response"
	 try{
 	 	set tmpStatus = process1.SendRequestAsync(claimsResponseFileTargetConfigName,reqObj)
	 }catch(ex){
		 Set tmpStatus = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError(process.%ConfigName,"Unable to write to file path :"_destinationFilePath_"Error:"_ex)   			 
	 }

 	 $$$TRACE("Response file sent..."_reqObj.DestinationFileName )

   quit tmpStatus

    set retCode = resp.retCode
	set retDesc =resp.retDesc
	set isSuccess=resp.isSuccess
	if (isSuccess="N"){
		set process1.errMsg = process1.errMsg_retDesc
		set process1.numErrBatchCounts =  process1.numErrBatchCounts +1
	}else{
		set process1.numSuccessBatchCounts =  process1.numSuccessBatchCounts +1
	}
	$$$TRACE("process1.numSuccessBatchCounts: "_process1.numSuccessBatchCounts)
	$$$TRACE("process1.numErrBatchCounts"_process1.numErrBatchCounts)
	$$$TRACE("process1.errMsg:"_process1.errMsg)

	quit $$$OK
